import csv
import io
from html.parser import HTMLParser


def _span(value):
    s = (value or '').strip()
    if s.isascii() and s.isdigit() and int(s) > 0:
        return int(s)
    return 1


def _layout(rows):
    grid = []
    carry = {}
    for cells in rows:
        row = {}
        for c in list(carry):
            n, text = carry[c]
            row[c] = text
            if n == 1:
                del carry[c]
            else:
                carry[c] = (n - 1, text)
        col = 0
        for text, cs, rs in cells:
            while col in row:
                col += 1
            for k in range(col, col + cs):
                row[k] = text
                if rs > 1:
                    carry[k] = (rs - 1, text)
            col += cs
        grid.append(row)
    width = max((max(r) + 1 for r in grid if r), default=0)
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator='\n')
    for r in grid:
        writer.writerow([r.get(c, '') for c in range(width)])
    return buf.getvalue()


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.depth = 0
        self.found = False
        self.done = False
        self.rows = []
        self.row = None
        self.cell = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == 'table':
            if self.depth:
                self.depth += 1
            elif dict(attrs).get('id') == self.table_id:
                self.found = True
                self.depth = 1
        elif self.depth == 1:
            if tag == 'tr':
                self.row = []
            elif tag in ('td', 'th') and self.row is not None:
                a = dict(attrs)
                self.cell = [[], _span(a.get('colspan')), _span(a.get('rowspan'))]

    def handle_endtag(self, tag):
        if self.done or not self.depth:
            return
        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self.done = True
        elif self.depth == 1:
            if tag in ('td', 'th') and self.cell is not None:
                parts, cs, rs = self.cell
                self.row.append((' '.join(''.join(parts).split()), cs, rs))
                self.cell = None
            elif tag == 'tr' and self.row is not None:
                self.rows.append(self.row)
                self.row = None

    def handle_data(self, data):
        if self.cell is not None and not self.done:
            self.cell[0].append(data)


def html_table_to_csv(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()
    if not parser.found:
        raise ValueError('table not found: %r' % (table_id,))
    if parser.row is not None:
        parser.rows.append(parser.row)
    return _layout(parser.rows)

