import math


def _gamma_q(a, x):
    if x <= 0:
        return 1.0
    log_front = -x + a * math.log(x) - math.lgamma(a)
    if x < a + 1:
        ap = a
        term = 1.0 / a
        total = term
        for _ in range(100000):
            ap += 1
            term *= x / ap
            total += term
            if abs(term) < abs(total) * 1e-16:
                break
        return max(0.0, 1.0 - total * math.exp(log_front))
    tiny = 1e-300
    b = x + 1 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 100000):
        an = -i * (i - a)
        b += 2
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < 1e-16:
            break
    return math.exp(log_front) * h


def item_location_independence_test(records):
    items = sorted({r[0] for r in records})
    locations = sorted({r[1] for r in records})
    if len(items) < 2 or len(locations) < 2:
        return None
    counts = {}
    for item, loc in records:
        counts[(item, loc)] = counts.get((item, loc), 0) + 1
    n = len(records)
    row_tot = {i: sum(counts.get((i, l), 0) for l in locations) for i in items}
    col_tot = {l: sum(counts.get((i, l), 0) for i in items) for l in locations}
    chi2 = 0.0
    for i in items:
        for l in locations:
            expected = row_tot[i] * col_tot[l] / n
            observed = counts.get((i, l), 0)
            chi2 += (observed - expected) ** 2 / expected
    dof = (len(items) - 1) * (len(locations) - 1)
    p = _gamma_q(dof / 2.0, chi2 / 2.0)
    return (float(chi2), float(p), int(dof))

