import pandas as pd
from scipy.stats import chi2_contingency


def item_location_independence_test(records):
    if not records:
        return None
    df = pd.DataFrame(list(records), columns=['Item', 'Location'])
    table = pd.crosstab(df['Item'], df['Location'])
    if table.shape[0] < 2 or table.shape[1] < 2:
        return None
    chi2, p, dof, _ = chi2_contingency(table.values, correction=False)
    return (float(chi2), float(p), int(dof))

