import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose
from statsmodels.stats.diagnostic import acorr_ljungbox


def residual_ljung_box(values, period, lags):
    x = np.asarray(values, dtype=float)
    if period < 2 or len(x) < 2 * period:
        raise ValueError("invalid period or series too short")
    resid = np.asarray(seasonal_decompose(x, model='additive', period=period).resid)
    resid = resid[~np.isnan(resid)]
    if lags < 1 or lags >= len(resid):
        raise ValueError("invalid lags")
    res = acorr_ljungbox(resid, lags=[lags])
    return (float(res['lb_stat'].iloc[-1]), float(res['lb_pvalue'].iloc[-1]))

