import struct

_M = 0xFFFFFFFF
_IV = (0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
       0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19)
_PERM = (2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8)
_CHUNK_START, _CHUNK_END, _PARENT, _ROOT, _KEYED = 1, 2, 4, 8, 16
_CHUNK_LEN = 1024


def _rotr(x, n):
    return ((x >> n) | (x << (32 - n))) & _M


def _g(s, a, b, c, d, x, y):
    s[a] = (s[a] + s[b] + x) & _M
    s[d] = _rotr(s[d] ^ s[a], 16)
    s[c] = (s[c] + s[d]) & _M
    s[b] = _rotr(s[b] ^ s[c], 12)
    s[a] = (s[a] + s[b] + y) & _M
    s[d] = _rotr(s[d] ^ s[a], 8)
    s[c] = (s[c] + s[d]) & _M
    s[b] = _rotr(s[b] ^ s[c], 7)


def _compress(cv, words, counter, block_len, flags):
    s = list(cv) + list(_IV[:4]) + [counter & _M, (counter >> 32) & _M, block_len, flags]
    m = list(words)
    for _ in range(7):
        _g(s, 0, 4, 8, 12, m[0], m[1])
        _g(s, 1, 5, 9, 13, m[2], m[3])
        _g(s, 2, 6, 10, 14, m[4], m[5])
        _g(s, 3, 7, 11, 15, m[6], m[7])
        _g(s, 0, 5, 10, 15, m[8], m[9])
        _g(s, 1, 6, 11, 12, m[10], m[11])
        _g(s, 2, 7, 8, 13, m[12], m[13])
        _g(s, 3, 4, 9, 14, m[14], m[15])
        m = [m[i] for i in _PERM]
    for i in range(8):
        s[i] ^= s[i + 8]
        s[i + 8] ^= cv[i]
    return s


def _words(block):
    return struct.unpack('<16I', block.ljust(64, b'\0'))


def _chunk(data, counter, key_words, flags):
    cv = list(key_words)
    blocks = [data[i:i + 64] for i in range(0, len(data), 64)] or [b'']
    for i, b in enumerate(blocks):
        f = flags | (_CHUNK_START if i == 0 else 0)
        if i == len(blocks) - 1:
            return (cv, _words(b), counter, len(b), f | _CHUNK_END)
        cv = _compress(cv, _words(b), counter, 64, f)[:8]


def _cv(out):
    cv, w, c, bl, f = out
    return _compress(cv, w, c, bl, f)[:8]


def _node(data, counter, key_words, flags):
    if len(data) <= _CHUNK_LEN:
        return _chunk(data, counter, key_words, flags)
    left = _CHUNK_LEN
    while left * 2 < len(data):
        left *= 2
    lcv = _cv(_node(data[:left], counter, key_words, flags))
    rcv = _cv(_node(data[left:], counter + left // _CHUNK_LEN, key_words, flags))
    return (list(key_words), lcv + rcv, 0, 64, flags | _PARENT)


def blake3_hash_hex(message, repeat, key, length):
    if key is not None and len(key) != 32:
        raise ValueError('key must be exactly 32 bytes')
    if length < 1:
        raise ValueError('length must be at least 1')
    if key is None:
        key_words, flags = _IV, 0
    else:
        key_words, flags = struct.unpack('<8I', bytes(key)), _KEYED
    data = bytes(message) * repeat
    cv, w, _, bl, f = _node(data, 0, key_words, flags)
    out = bytearray()
    counter = 0
    while len(out) < length:
        s = _compress(cv, w, counter, bl, f | _ROOT)
        out += struct.pack('<16I', *s)
        counter += 1
    return bytes(out[:length]).hex()

