import statistics


def _betacf(a, b, x):
    MAXIT = 2000
    EPS = 3e-15
    FPMIN = 1e-300
    qab = a + b
    qap = a + 1.0
    qam = a - 1.0
    c = 1.0
    d = 1.0 - qab * x / qap
    if abs(d) < FPMIN:
        d = FPMIN
    d = 1.0 / d
    h = d
    for m in range(1, MAXIT + 1):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aa / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aa / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        de = d * c
        h *= de
        if abs(de - 1.0) < EPS:
            break
    return h


def _betainc(a, b, x):
    if x <= 0.0:
        return 0.0
    if x >= 1.0:
        return 1.0
    lbeta = math.lgamma(a) + math.lgamma(b) - math.lgamma(a + b)
    if x < (a + 1.0) / (a + b + 2.0):
        front = math.exp(a * math.log(x) + b * math.log1p(-x) - lbeta) / a
        return front * _betacf(a, b, x)
    front = math.exp(a * math.log(x) + b * math.log1p(-x) - lbeta) / b
    return 1.0 - front * _betacf(b, a, 1.0 - x)


def _t_sf(t, df):
    x = df / (df + t * t)
    return 0.5 * _betainc(df / 2.0, 0.5, x)


def _t_ppf(p, df):
    if p == 0.5:
        return 0.0
    q = min(p, 1.0 - p)
    lo, hi = 0.0, 1.0
    while _t_sf(hi, df) > q:
        lo = hi
        hi *= 2.0
    for _ in range(300):
        mid = (lo + hi) / 2.0
        if _t_sf(mid, df) > q:
            lo = mid
        else:
            hi = mid
        if hi - lo <= 1e-14 * hi:
            break
    t = (lo + hi) / 2.0
    return t if p > 0.5 else -t


def t_qq_plot_data(values, df):
    if df <= 0:
        raise ValueError('df must be positive')
    n = len(values)
    if n < 3:
        raise ValueError('need at least 3 values')
    if len(set(values)) == 1:
        raise ValueError('values must not all be identical')
    ordered = sorted(float(v) for v in values)
    last = 0.5 ** (1.0 / n)
    positions = [1.0 - last] + [(i - 0.3175) / (n + 0.365) for i in range(2, n)] + [last]
    theoretical = [_t_ppf(p, df) for p in positions]
    slope, intercept = statistics.linear_regression(theoretical, ordered)
    r = statistics.correlation(theoretical, ordered)
    return (theoretical, ordered, float(slope), float(intercept), float(r))

