import math


def _centroid(pts, idx):
    idx = list(idx)
    dim = len(pts[0])
    return [sum(pts[i][d] for i in idx) / len(idx) for d in range(dim)]


def _silhouette(pts, labels, groups):
    total = 0.0
    for i, p in enumerate(pts):
        own = labels[i]
        members = groups[own]
        if len(members) == 1:
            continue
        a = sum(math.dist(p, pts[j]) for j in members) / (len(members) - 1)
        b = min(sum(math.dist(p, pts[j]) for j in idx) / len(idx)
                for lab, idx in groups.items() if lab != own)
        m = max(a, b)
        if m > 0:
            total += (b - a) / m
    return total / len(pts)


def _calinski_harabasz(pts, clusters):
    n = len(pts)
    k = len(clusters)
    overall = _centroid(pts, range(n))
    extra = 0.0
    intra = 0.0
    for idx in clusters:
        c = _centroid(pts, idx)
        extra += len(idx) * sum((a - b) ** 2 for a, b in zip(c, overall))
        intra += sum(sum((a - b) ** 2 for a, b in zip(pts[i], c)) for i in idx)
    if intra == 0.0:
        return 1.0
    return extra * (n - k) / (intra * (k - 1.0))


def _davies_bouldin(pts, clusters):
    k = len(clusters)
    cents = [_centroid(pts, idx) for idx in clusters]
    spread = [sum(math.dist(pts[i], c) for i in idx) / len(idx)
              for idx, c in zip(clusters, cents)]
    if all(abs(s) <= 1e-8 for s in spread):
        return 0.0
    cd = [[math.dist(a, b) for b in cents] for a in cents]
    if all(abs(d) <= 1e-8 for row in cd for d in row):
        return 0.0
    scores = []
    for i in range(k):
        best = 0.0
        for j in range(k):
            if j == i or cd[i][j] == 0:
                continue
            best = max(best, (spread[i] + spread[j]) / cd[i][j])
        scores.append(best)
    return sum(scores) / k


def cluster_quality_scores(points, labels):
    pts = [[float(v) for v in p] for p in points]
    n = len(pts)
    if n != len(labels) or n == 0:
        raise ValueError('points and labels must have the same non-zero length')
    dim = len(pts[0])
    if any(len(p) != dim for p in pts):
        raise ValueError('all points must have the same dimension')
    groups = {}
    for i, lab in enumerate(labels):
        groups.setdefault(lab, []).append(i)
    k = len(groups)
    if k < 2 or k >= n:
        raise ValueError('number of labels must be between 2 and n_samples - 1')
    clusters = list(groups.values())
    return {
        'silhouette': float(_silhouette(pts, labels, groups)),
        'calinski_harabasz': float(_calinski_harabasz(pts, clusters)),
        'davies_bouldin': float(_davies_bouldin(pts, clusters)),
    }

