import base64
import math


def _der_length(n):
    if n < 0x80:
        return bytes([n])
    b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
    return bytes([0x80 | len(b)]) + b


def _der_tlv(tag, body):
    return bytes([tag]) + _der_length(len(body)) + body


def _der_int(v):
    return _der_tlv(0x02, v.to_bytes(v.bit_length() // 8 + 1, 'big'))


def _der_sequence_of_ints(values):
    return _der_tlv(0x30, b''.join(_der_int(v) for v in values))


def _pem(der, label):
    b64 = base64.b64encode(der).decode('ascii')
    lines = ['-----BEGIN %s-----' % label]
    lines.extend(b64[i:i + 64] for i in range(0, len(b64), 64))
    lines.append('-----END %s-----' % label)
    return '\n'.join(lines) + '\n'


def rsa_key_pems(p, q, e):
    if p == q:
        raise ValueError('p and q must differ')
    phi = (p - 1) * (q - 1)
    if math.gcd(e, phi) != 1:
        raise ValueError('e must be coprime to (p-1)(q-1)')
    n = p * q
    d = pow(e, -1, phi)
    exp1 = d % (p - 1)
    exp2 = d % (q - 1)
    coef = pow(q, -1, p)
    priv_der = _der_sequence_of_ints([0, n, e, d, p, q, exp1, exp2, coef])
    pub_der = _der_sequence_of_ints([n, e])
    return (_pem(priv_der, 'RSA PRIVATE KEY'), _pem(pub_der, 'RSA PUBLIC KEY'))

