import re
import math
from collections import Counter


def _tok(s):
    return re.findall(r'\w+', s.lower())


def _ngrams(tokens, n):
    return Counter(tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1))


def bleu4_against_references(candidate, references):
    if not references:
        raise ValueError('references must not be empty')
    hyp = _tok(candidate)
    refs = [_tok(r) for r in references]
    if not hyp:
        return 0.0
    log_sum = 0.0
    for n in range(1, 5):
        hyp_counts = _ngrams(hyp, n)
        max_ref = Counter()
        for r in refs:
            for g, c in _ngrams(r, n).items():
                if c > max_ref[g]:
                    max_ref[g] = c
        num = sum(min(c, max_ref[g]) for g, c in hyp_counts.items())
        den = max(1, sum(hyp_counts.values()))
        if num == 0:
            return 0.0
        log_sum += 0.25 * math.log(num / den)
    c = len(hyp)
    r = min((len(x) for x in refs), key=lambda L: (abs(L - c), L))
    bp = 1.0 if c > r else math.exp(1 - r / c)
    return bp * math.exp(log_sum)

