import numpy as np


def pca_project(rows, n_components):
    if len(rows) < 2:
        raise ValueError('need at least two rows')
    d = len(rows[0])
    if d == 0 or any(len(r) != d for r in rows):
        raise ValueError('rows must be non-empty and equal length')
    if not 1 <= n_components <= d:
        raise ValueError('bad n_components')
    X = np.asarray(rows, dtype=float)
    if np.all(X == X[0]):
        raise ValueError('all rows identical')
    Xc = X - X.mean(axis=0)
    cov = Xc.T @ Xc / (X.shape[0] - 1)
    w, v = np.linalg.eigh(cov)
    order = np.argsort(w)[::-1][:n_components]
    v = v[:, order]
    idx = np.argmax(np.abs(v), axis=0)
    v = v * np.sign(v[idx, np.arange(n_components)])
    return {'scores': (Xc @ v).tolist(), 'explained_variance_ratio': (w[order] / np.trace(cov)).tolist()}

