import re
from html.parser import HTMLParser

_VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'keygen', 'link', 'menuitem', 'meta', 'param', 'source', 'track', 'wbr', 'basefont', 'bgsound', 'command', 'frame', 'image', 'isindex', 'nextid', 'spacer'}

_COMPOUND = re.compile(r'''(?P<tag>\*|[A-Za-z][\w-]*)?(?P<rest>(?:\.[\w-]+|\#[\w-]+|\[\s*[\w-]+\s*(?:=\s*(?:"[^"]*"|'[^']*'|[\w-]+)\s*)?\])*)''')
_SIMPLE = re.compile(r'''\.([\w-]+)|\#([\w-]+)|\[\s*([\w-]+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([\w-]+))\s*)?\]''')
_COMB = re.compile(r'\s*>\s*|\s+')


class _Node:
    __slots__ = ('tag', 'attrs', 'parent', 'children')

    def __init__(self, tag, attrs, parent):
        self.tag = tag
        self.attrs = attrs
        self.parent = parent
        self.children = []


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None, {}, None)
        self.stack = [self.root]
        self.elements = []

    def handle_starttag(self, tag, attrs):
        parent = self.stack[-1]
        node = _Node(tag, {k: ('' if v is None else v) for k, v in attrs}, parent)
        parent.children.append(node)
        self.elements.append(node)
        if tag not in _VOID:
            self.stack.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _text(node):
    parts = []
    for c in node.children:
        parts.append(c if isinstance(c, str) else _text(c))
    return ''.join(parts)


def _parse_compound(m):
    tag = m.group('tag')
    tag = None if tag in (None, '*') else tag.lower()
    classes, ids, attrs = [], [], []
    for p in _SIMPLE.finditer(m.group('rest')):
        if p.group(1) is not None:
            classes.append(p.group(1))
        elif p.group(2) is not None:
            ids.append(p.group(2))
        else:
            val = next((g for g in p.group(4, 5, 6) if g is not None), None)
            attrs.append((p.group(3).lower(), val))
    return tag, classes, ids, attrs


def _parse_selector(selector):
    s = selector.strip()
    pos = 0
    parts, combs = [], []
    while True:
        m = _COMPOUND.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError('invalid selector')
        parts.append(_parse_compound(m))
        pos = m.end()
        if pos == len(s):
            break
        c = _COMB.match(s, pos)
        if not c:
            raise ValueError('invalid selector')
        combs.append('>' if '>' in c.group() else ' ')
        pos = c.end()
    return parts, combs


def _compound_match(node, comp):
    tag, classes, ids, attrs = comp
    if tag is not None and node.tag != tag:
        return False
    if classes:
        have = set(node.attrs.get('class', '').split())
        if not all(c in have for c in classes):
            return False
    for i in ids:
        if node.attrs.get('id') != i:
            return False
    for name, val in attrs:
        if name not in node.attrs:
            return False
        if val is not None and node.attrs[name] != val:
            return False
    return True


def texts_matching_selector(html, selector):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    root = builder.root
    parts, combs = _parse_selector(selector)

    def match(node, i):
        if node is root or not _compound_match(node, parts[i]):
            return False
        if i == 0:
            return True
        p = node.parent
        if combs[i - 1] == '>':
            return p is not root and match(p, i - 1)
        while p is not root:
            if match(p, i - 1):
                return True
            p = p.parent
        return False

    last = len(parts) - 1
    return [_text(n).strip() for n in builder.elements if match(n, last)]

