import numpy as np
import statsmodels.api as sm


def ols_regression_summary(features, target):
    n = len(target)
    if n == 0 or len(features) != n:
        raise ValueError('invalid input sizes')
    k = len(features[0])
    if k == 0 or any(len(r) != k for r in features):
        raise ValueError('rows must have equal non-zero length')
    if n <= k + 1:
        raise ValueError('not enough observations')
    X = sm.add_constant(np.asarray(features, dtype=float), has_constant='add')
    y = np.asarray(target, dtype=float)
    if np.linalg.matrix_rank(X) < X.shape[1]:
        raise ValueError('design matrix is rank-deficient')
    if np.all(y == y[0]):
        raise ValueError('target is constant')
    res = sm.OLS(y, X).fit()
    if res.ssr < 1e-10 * res.centered_tss:
        raise ValueError('exact fit')
    coefs = [[float(a), float(b), float(c), float(d)]
             for a, b, c, d in zip(res.params, res.bse, res.tvalues, res.pvalues)]
    return {'coefficients': coefs, 'r_squared': float(res.rsquared),
            'f_statistic': float(res.fvalue), 'f_pvalue': float(res.f_pvalue)}

