import math


def _check(matrix):
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        raise ValueError("matrix must be non-empty and square")
    a = [[float(x) for x in row] for row in matrix]
    for i in range(n):
        for j in range(i + 1, n):
            if abs(a[i][j] - a[j][i]) > 1e-9:
                raise ValueError("matrix must be symmetric")
    return a


def _rotate(a, p, q):
    n = len(a)
    apq = a[p][q]
    if apq == 0.0:
        return
    theta = (a[q][q] - a[p][p]) / (2.0 * apq)
    sign = 1.0 if theta >= 0 else -1.0
    t = sign / (abs(theta) + math.hypot(theta, 1.0))
    c = 1.0 / math.sqrt(t * t + 1.0)
    s = t * c
    for k in range(n):
        akp, akq = a[k][p], a[k][q]
        a[k][p] = c * akp - s * akq
        a[k][q] = s * akp + c * akq
    for k in range(n):
        apk, aqk = a[p][k], a[q][k]
        a[p][k] = c * apk - s * aqk
        a[q][k] = s * apk + c * aqk
    a[p][q] = 0.0
    a[q][p] = 0.0


def symmetric_matrix_eigenvalues(matrix):
    a = _check(matrix)
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            avg = (a[i][j] + a[j][i]) / 2.0
            a[i][j] = a[j][i] = avg
    total = sum(x * x for row in a for x in row)
    for _ in range(200):
        off = sum(a[i][j] ** 2 for i in range(n) for j in range(n) if i != j)
        if off == 0.0 or off <= 1e-30 * total:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                _rotate(a, p, q)
    return sorted(a[i][i] for i in range(n))

