import ast
import math
import struct

_MAGIC = b'\x93\x4e\x55\x4d\x50\x59'
_CODES = {
    ('b', 1): '?', ('i', 1): 'b', ('u', 1): 'B',
    ('i', 2): 'h', ('u', 2): 'H', ('i', 4): 'i', ('u', 4): 'I',
    ('i', 8): 'q', ('u', 8): 'Q',
    ('f', 2): 'e', ('f', 4): 'f', ('f', 8): 'd',
}
_ORDERS = {'<': '<', '>': '>', '|': '<', '=': '='}


def decode_npy_array(blob):
    blob = bytes(blob)
    if len(blob) < 10 or blob[:6] != _MAGIC:
        raise ValueError('not an NPY file')
    version = (blob[6], blob[7])
    if version == (1, 0):
        (hlen,) = struct.unpack_from('<H', blob, 8)
        start, enc = 10, 'latin1'
    elif version in ((2, 0), (3, 0)):
        if len(blob) < 12:
            raise ValueError('truncated header length')
        (hlen,) = struct.unpack_from('<I', blob, 8)
        start = 12
        enc = 'utf8' if version[0] == 3 else 'latin1'
    else:
        raise ValueError('unsupported format version')
    raw = blob[start:start + hlen]
    if len(raw) < hlen:
        raise ValueError('truncated header')
    try:
        header = ast.literal_eval(raw.decode(enc).strip())
    except (ValueError, SyntaxError, UnicodeDecodeError) as exc:
        raise ValueError('malformed header') from exc
    if not isinstance(header, dict) or set(header) != {'descr', 'fortran_order', 'shape'}:
        raise ValueError('malformed header')
    descr, fortran, shape = header['descr'], header['fortran_order'], header['shape']
    if not isinstance(shape, tuple) or not all(isinstance(n, int) and n >= 0 for n in shape):
        raise ValueError('bad shape')
    if not isinstance(fortran, bool):
        raise ValueError('bad fortran_order')
    if not isinstance(descr, str) or len(descr) < 3 or descr[0] not in _ORDERS:
        raise ValueError('unsupported dtype')
    try:
        size = int(descr[2:])
    except ValueError as exc:
        raise ValueError('unsupported dtype') from exc
    code = _CODES.get((descr[1], size))
    if code is None:
        raise ValueError('unsupported dtype')
    count = math.prod(shape)
    offset = start + hlen
    data = blob[offset:offset + count * size]
    if len(data) < count * size:
        raise ValueError('truncated data')
    flat = struct.unpack('%s%d%s' % (_ORDERS[descr[0]], count, code), data)
    ndim = len(shape)
    strides = [1] * ndim
    if fortran:
        for k in range(1, ndim):
            strides[k] = strides[k - 1] * shape[k - 1]
    else:
        for k in range(ndim - 2, -1, -1):
            strides[k] = strides[k + 1] * shape[k + 1]

    def build(dim, pos):
        if dim == ndim:
            return flat[pos]
        return [build(dim + 1, pos + i * strides[dim]) for i in range(shape[dim])]

    return build(0, 0)

