import math
from collections import Counter


def _ngrams(tokens, n):
    return Counter(tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1))


def corpus_bleu_score(references, hypotheses):
    if len(references) != len(hypotheses) or not hypotheses:
        raise ValueError("references and hypotheses must be non-empty lists of equal length")
    num = [0] * 5
    den = [0] * 5
    hyp_len = 0
    ref_len = 0
    for refs, hyp in zip(references, hypotheses):
        h = hyp.split()
        rs = [r.split() for r in refs]
        for n in range(1, 5):
            hc = _ngrams(h, n)
            max_counts = Counter()
            for r in rs:
                for g, c in _ngrams(r, n).items():
                    if c > max_counts[g]:
                        max_counts[g] = c
            num[n] += sum(min(c, max_counts[g]) for g, c in hc.items())
            den[n] += max(1, sum(hc.values()))
        hl = len(h)
        hyp_len += hl
        ref_len += min((len(r) for r in rs), key=lambda L: (abs(L - hl), L))
    if any(num[n] == 0 for n in range(1, 5)):
        return 0.0
    if hyp_len > ref_len:
        bp = 1.0
    else:
        bp = math.exp(1 - ref_len / hyp_len)
    log_sum = sum(0.25 * math.log(num[n] / den[n]) for n in range(1, 5))
    return float(bp * math.exp(log_sum))

