_FIXED = {'D', 'B', 'MS', 'ME', 'BMS', 'BME', 'SMS', 'SME', 'QS', 'QE', 'YS', 'YE'}


def _parse(freq):
    if freq in _FIXED:
        return (freq,)
    m = re.fullmatch(r'W-(MON|TUE|WED|THU|FRI|SAT|SUN)', freq)
    if m:
        return ('W', _DAYS.index(m.group(1)))
    m = re.fullmatch(r'WOM-([1-4])(MON|TUE|WED|THU|FRI|SAT|SUN)', freq)
    if m:
        return ('WOM', int(m.group(1)), _DAYS.index(m.group(2)))
    raise ValueError('unsupported frequency: %r' % (freq,))


def _is_on(rule, d):
    kind = rule[0]
    wd = d.weekday()
    last_day = (d + timedelta(days=1)).month != d.month
    if kind == 'D':
        return True
    if kind == 'B':
        return wd < 5
    if kind == 'MS':
        return d.day == 1
    if kind == 'ME':
        return last_day
    if kind == 'BMS':
        return wd < 5 and (d.day == 1 or (d.day <= 3 and wd == 0))
    if kind == 'BME':
        return wd < 5 and (last_day or (wd == 4 and (d + timedelta(days=3)).month != d.month))
    if kind == 'SMS':
        return d.day in (1, 15)
    if kind == 'SME':
        return d.day == 15 or last_day
    if kind == 'QS':
        return d.day == 1 and d.month in (1, 4, 7, 10)
    if kind == 'QE':
        return last_day and d.month in (3, 6, 9, 12)
    if kind == 'YS':
        return d.month == 1 and d.day == 1
    if kind == 'YE':
        return d.month == 12 and d.day == 31
    if kind == 'W':
        return wd == rule[1]
    if kind == 'WOM':
        return wd == rule[2] and (d.day - 1) // 7 == rule[1] - 1
    return False


def price_schedule(start_date, prices, freq):
    rule = _parse(freq)
    d = date.fromisoformat(start_date)
    result = []
    i = 0
    while i < len(prices):
        if _is_on(rule, d):
            result.append((d.isoformat(), float(prices[i])))
            i += 1
        d += timedelta(days=1)
    return result

