import re


def _unfold(text):
    lines = []
    for raw in re.split(r'\r\n|\r|\n', text):
        if raw[:1] in (' ', '\t') and lines:
            lines[-1] += raw[1:]
        elif raw.strip():
            lines.append(raw)
    return lines


def _split_line(line):
    in_quote = False
    for i, ch in enumerate(line):
        if ch == '"':
            in_quote = not in_quote
        elif ch == ':' and not in_quote:
            head, value = line[:i], line[i + 1:]
            break
    else:
        return None
    name = head.split(';', 1)[0]
    if '.' in name:
        name = name.rsplit('.', 1)[1]
    return name.strip().upper(), value


def _unescape(value):
    out = []
    i = 0
    while i < len(value):
        ch = value[i]
        if ch == '\\' and i + 1 < len(value):
            nxt = value[i + 1]
            out.append('\n' if nxt in 'nN' else nxt)
            i += 2
        else:
            out.append(ch)
            i += 1
    return ''.join(out)


def extract_vcard_contacts(vcf_text):
    result = []
    card = None
    for line in _unfold(vcf_text):
        parsed = _split_line(line)
        if parsed is None:
            continue
        name, value = parsed
        if name == 'BEGIN' and value.strip().upper() == 'VCARD':
            card = [None, []]
        elif name == 'END' and value.strip().upper() == 'VCARD':
            if card is not None:
                result.append((card[0], card[1]))
                card = None
        elif card is not None:
            if name == 'FN' and card[0] is None:
                card[0] = _unescape(value)
            elif name == 'EMAIL':
                card[1].append(_unescape(value).replace('@', '[at]'))
    return result

