from html.parser import HTMLParser

VOID_TAGS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'keygen',
    'link', 'menuitem', 'meta', 'param', 'source', 'track', 'wbr',
    'basefont', 'bgsound', 'command', 'frame', 'image', 'isindex',
    'nextid', 'spacer',
}


class _Node:
    def __init__(self, tag, attrs):
        self.tag = tag
        self.attrs = attrs
        self.children = []

    def classes(self):
        return self.attrs.get('class', '').split()


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None, {})
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, {k: (v if v is not None else '') for k, v in attrs})
        self.stack[-1].children.append(node)
        if tag not in VOID_TAGS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _descendants(node):
    for child in node.children:
        if isinstance(child, _Node):
            yield child
            yield from _descendants(child)


def _text(node):
    parts = []
    for child in node.children:
        if isinstance(child, _Node):
            parts.append(_text(child))
        else:
            parts.append(child)
    return ''.join(parts)


def _find_first(node, tag, cls=None):
    for d in _descendants(node):
        if d.tag == tag and (cls is None or cls in d.classes()):
            return d
    return None


def extract_article_records(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    records = []
    for div in _descendants(builder.root):
        if div.tag != 'div' or 'container' not in div.classes():
            continue
        h1 = _find_first(div, 'h1')
        date = _find_first(div, 'span', 'date')
        author = _find_first(div, 'span', 'author')
        records.append((
            _text(h1).strip() if h1 is not None else 'No Title',
            _text(date).strip() if date is not None else 'No Date',
            _text(author).strip() if author is not None else 'No Author',
        ))
    return records

