def color_state_independence_test(observations):
    pairs = []
    for s in observations:
        parts = s.split(':')
        if len(parts) != 2:
            raise ValueError('each observation must contain exactly one colon')
        pairs.append(parts)
    if not pairs:
        return None
    df = pd.DataFrame(pairs, columns=['color', 'state'])
    table = pd.crosstab(df['color'], df['state'])
    if table.shape[0] < 2 or table.shape[1] < 2:
        return None
    res = chi2_contingency(table.values, correction=False)
    return (float(res[0]), float(res[1]), int(res[2]))

