import csv
import io
import re
import sqlite3

_INT = re.compile(r'[+-]?\d+\Z')
_NUM = re.compile(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?\Z')


def _column_type(values):
    if not values:
        return 'TEXT'
    present = [v for v in values if v != '']
    if not present:
        return 'REAL'
    if all(_INT.match(v) for v in present):
        return 'INTEGER' if len(present) == len(values) else 'REAL'
    if all(_NUM.match(v) for v in present):
        return 'REAL'
    return 'TEXT'


def _convert(value, ctype):
    if value == '':
        return None
    if ctype == 'INTEGER':
        return int(value)
    if ctype == 'REAL':
        return float(value)
    return value


def _quote(name):
    return '"' + name.replace('"', '""') + '"'


def query_csv_with_sql(csv_text, query):
    records = [r for r in csv.reader(io.StringIO(csv_text)) if r]
    header, body = records[0], records[1:]
    types = [_column_type([row[i] for row in body]) for i in range(len(header))]
    conn = sqlite3.connect(':memory:')
    try:
        cols_sql = ', '.join('%s %s' % (_quote(h), t) for h, t in zip(header, types))
        conn.execute('CREATE TABLE data (%s)' % cols_sql)
        placeholders = ', '.join('?' for _ in header)
        conn.executemany(
            'INSERT INTO data VALUES (%s)' % placeholders,
            [[_convert(v, t) for v, t in zip(row, types)] for row in body],
        )
        try:
            cur = conn.execute(query)
            columns = [d[0] for d in cur.description] if cur.description else []
            rows = [list(r) for r in cur.fetchall()] if cur.description else []
        except sqlite3.Error as e:
            raise ValueError('Error running query: %s' % e) from e
    finally:
        conn.close()
    return {'columns': columns, 'rows': rows}

import json
