def _is_type(value, name):
    if name == 'null':
        return value is None
    if name == 'boolean':
        return isinstance(value, bool)
    if name == 'integer':
        if isinstance(value, bool):
            return False
        return isinstance(value, int) or (isinstance(value, float) and value.is_integer())
    if name == 'number':
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if name == 'string':
        return isinstance(value, str)
    if name == 'array':
        return isinstance(value, list)
    if name == 'object':
        return isinstance(value, dict)
    return False


def _equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, str) or isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    return a == b


def _validate(inst, schema, path, out):
    if 'type' in schema:
        types = schema['type'] if isinstance(schema['type'], list) else [schema['type']]
        if not any(_is_type(inst, t) for t in types):
            out.add(path)
    if 'enum' in schema and not any(_equal(inst, e) for e in schema['enum']):
        out.add(path)
    if 'const' in schema and not _equal(inst, schema['const']):
        out.add(path)
    if _is_type(inst, 'number'):
        if 'minimum' in schema and inst < schema['minimum']:
            out.add(path)
        if 'maximum' in schema and inst > schema['maximum']:
            out.add(path)
        if 'exclusiveMinimum' in schema and inst <= schema['exclusiveMinimum']:
            out.add(path)
        if 'exclusiveMaximum' in schema and inst >= schema['exclusiveMaximum']:
            out.add(path)
    if isinstance(inst, str):
        if 'minLength' in schema and len(inst) < schema['minLength']:
            out.add(path)
        if 'maxLength' in schema and len(inst) > schema['maxLength']:
            out.add(path)
        if 'pattern' in schema and not re.search(schema['pattern'], inst):
            out.add(path)
    if isinstance(inst, list):
        if 'minItems' in schema and len(inst) < schema['minItems']:
            out.add(path)
        if 'maxItems' in schema and len(inst) > schema['maxItems']:
            out.add(path)
        if 'items' in schema:
            for i, item in enumerate(inst):
                _validate(item, schema['items'], path + _escape(i), out)
    if isinstance(inst, dict):
        props = schema.get('properties', {})
        for key, sub in props.items():
            if key in inst:
                _validate(inst[key], sub, path + _escape(key), out)
        for key in schema.get('required', []):
            if key not in inst:
                out.add(path)
        if 'additionalProperties' in schema:
            extra_schema = schema['additionalProperties']
            extras = [k for k in inst if k not in props]
            if isinstance(extra_schema, dict):
                for key in extras:
                    _validate(inst[key], extra_schema, path + _escape(key), out)
            elif not extra_schema and extras:
                out.add(path)


def find_schema_violations(document_text, schema):
    instance = json.loads(document_text)
    out = set()
    _validate(instance, schema, '', out)
    return sorted(out)

