import math

_FPMIN = 1e-300
_EPS = 1e-15
_MAXIT = 100000


def _prefactor(a, x):
    return math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gser(a, x):
    ap = a
    term = 1.0 / a
    total = term
    for _ in range(_MAXIT):
        ap += 1.0
        term *= x / ap
        total += term
        if abs(term) < abs(total) * _EPS:
            break
    return total * _prefactor(a, x)


def _gcf(a, x):
    b = x + 1.0 - a
    c = 1.0 / _FPMIN
    d = 1.0 / b
    h = d
    for i in range(1, _MAXIT):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < _FPMIN:
            d = _FPMIN
        c = b + an / c
        if abs(c) < _FPMIN:
            c = _FPMIN
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < _EPS:
            break
    return h * _prefactor(a, x)


def _reg_lower(a, x):
    if x <= 0:
        return 0.0
    if x < a + 1.0:
        return _gser(a, x)
    return 1.0 - _gcf(a, x)


def _reg_upper(a, x):
    if x <= 0:
        return 1.0
    if x < a + 1.0:
        return 1.0 - _gser(a, x)
    return _gcf(a, x)


def _chi2_cdf(x, df):
    return _reg_lower(df / 2.0, x / 2.0)


def _chi2_sf(x, df):
    return _reg_upper(df / 2.0, x / 2.0)


def _chi2_ppf(q, df):
    lo = 0.0
    hi = max(1.0, float(df))
    while _chi2_cdf(hi, df) < q:
        lo = hi
        hi *= 2.0
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if _chi2_cdf(mid, df) < q:
            lo = mid
        else:
            hi = mid
        if hi - lo <= 1e-14 * hi:
            break
    return (lo + hi) / 2.0


def pet_shop_sales_report(daily_customers, sales, confidence):
    n = len(daily_customers)
    if n == 0 or not (0 < confidence < 1):
        raise ValueError('invalid customers or confidence')
    counts = list(sales.values())
    if len(counts) < 2 or sum(counts) == 0:
        raise ValueError('invalid sales')
    total = sum(daily_customers)
    alpha = 1.0 - confidence
    low = 0.0 if total == 0 else _chi2_ppf(alpha / 2.0, 2 * total) / 2.0
    high = _chi2_ppf(1.0 - alpha / 2.0, 2 * total + 2) / 2.0
    k = len(counts)
    expected = sum(counts) / k
    chi = sum((c - expected) ** 2 for c in counts) / expected
    p = _chi2_sf(chi, k - 1)
    return {'mean': total / n, 'ci': (low / n, high / n), 'chi2': float(chi), 'p_value': float(p)}

import re
from datetime import date, timedelta

_DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']
_FIXED = {'daily', 'business', 'month-start', 'month-end', 'bmonth-start', 'bmonth-end',
          'semimonth-start', 'semimonth-end', 'quarter-start', 'quarter-end',
          'year-start', 'year-end'}


def _parse(freq):
    if freq in _FIXED:
        return (freq,)
    m = re.fullmatch(r'weekly-(mon|tue|wed|thu|fri|sat|sun)', freq)
    if m:
        return ('weekly', _DAYS.index(m.group(1)))
    m = re.fullmatch(r'nth-weekday-([1-4])-(mon|tue|wed|thu|fri|sat|sun)', freq)
    if m:
        return ('nth', int(m.group(1)), _DAYS.index(m.group(2)))
    raise ValueError('unsupported frequency: %r' % (freq,))


def _is_on(rule, d):
    kind = rule[0]
    wd = d.weekday()
    last_day = (d + timedelta(days=1)).month != d.month
    if kind == 'daily':
        return True
    if kind == 'business':
        return wd < 5
    if kind == 'month-start':
        return d.day == 1
    if kind == 'month-end':
        return last_day
    if kind == 'bmonth-start':
        return wd < 5 and (d.day == 1 or (d.day <= 3 and wd == 0))
    if kind == 'bmonth-end':
        return wd < 5 and (last_day or (wd == 4 and (d + timedelta(days=3)).month != d.month))
    if kind == 'semimonth-start':
        return d.day in (1, 15)
    if kind == 'semimonth-end':
        return d.day == 15 or last_day
    if kind == 'quarter-start':
        return d.day == 1 and d.month in (1, 4, 7, 10)
    if kind == 'quarter-end':
        return last_day and d.month in (3, 6, 9, 12)
    if kind == 'year-start':
        return d.month == 1 and d.day == 1
    if kind == 'year-end':
        return d.month == 12 and d.day == 31
    if kind == 'weekly':
        return wd == rule[1]
    if kind == 'nth':
        return wd == rule[2] and (d.day - 1) // 7 == rule[1] - 1
    return False


def price_schedule(start_date, prices, freq):
    rule = _parse(freq)
    d = date.fromisoformat(start_date)
    result = []
    i = 0
    while i < len(prices):
        if _is_on(rule, d):
            result.append((d.isoformat(), float(prices[i])))
            i += 1
        d += timedelta(days=1)
    return result

