    'daily': pd.offsets.Day(), 'business': pd.offsets.BDay(),
    'month-start': pd.offsets.MonthBegin(), 'month-end': pd.offsets.MonthEnd(),
    'bmonth-start': pd.offsets.BMonthBegin(), 'bmonth-end': pd.offsets.BMonthEnd(),
