import numpy as np
from sklearn.linear_model import Ridge
from sklearn.model_selection import KFold, cross_val_score


def ridge_kfold_r2(features, targets, alpha, n_folds):
    if len(targets) == 0 or len(features) != len(targets):
        raise ValueError('invalid features/targets')
    if len(features[0]) == 0 or any(len(r) != len(features[0]) for r in features):
        raise ValueError('ragged or empty rows')
    X = np.asarray(features, dtype=float)
    y = np.asarray(targets, dtype=float)
    if alpha < 0:
        raise ValueError('alpha must be non-negative')
    if n_folds < 2 or n_folds > len(y) // 2:
        raise ValueError('invalid number of folds')
    cv = KFold(n_splits=n_folds)
    if any(np.ptp(y[te]) == 0 for _, te in cv.split(X)):
        raise ValueError('a fold has constant targets')
    scores = cross_val_score(Ridge(alpha=alpha), X, y, cv=cv, scoring='r2')
    return (float(np.mean(scores)), [float(s) for s in scores])
